package org.apache.commons.math.geometry.euclidean.threed;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.geometry.euclidean.threed.Rotation;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math3.exception.MathIllegalArgumentException;
import org.apache.commons.math3.util.FastMath;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for Rotation.getAngle() to maximize branch and line coverage.
 */
public class Rotation_getAngle_TriageGen1Test {

    private static final double EPSILON = 1e-12;

    /**
     * Tests the first branch: (q0 < -0.1) || (q0 > 0.1)
     * Formula: 2 * asin(sqrt(q1^2 + q2^2 + q3^2))
     */
    @Test
    public void testGetAngle_Branch1_PositiveQ0() {
        // q0 = 0.5 ( > 0.1)
        // q1 = 0.5, q2 = 0.5, q3 = 0.5
        // sqrt(0.25 + 0.25 + 0.25) = sqrt(0.75)
        // angle = 2 * asin(sqrt(0.75))
        double q0 = 0.5;
        double q1 = 0.5;
        double q2 = 0.5;
        double q3 = 0.5;
        Rotation rotation = new Rotation(q0, q1, q2, q3, true);

        double expected = 2 * FastMath.asin(FastMath.sqrt(q1 * q1 + q2 * q2 + q3 * q3));
        Assert.assertEquals(expected, rotation.getAngle(), EPSILON);
    }

    @Test
    public void testGetAngle_Branch1_NegativeQ0() {
        // q0 = -0.5 ( < -0.1)
        double q0 = -0.5;
        double q1 = 0.1;
        double q2 = 0.1;
        double q3 = 0.1;
        Rotation rotation = new Rotation(q0, q1, q2, q3, true);

        double expected = 2 * FastMath.asin(FastMath.sqrt(q1 * q1 + q2 * q2 + q3 * q3));
        Assert.assertEquals(expected, rotation.getAngle(), EPSILON);
    }

    /**
     * Tests the second branch: q0 is not in (-0.1, 0.1) AND q0 < 0
     * Since the first 'if' handles q0 < -0.1, this branch is reached if 
     * the logic allows q0 to be between -0.1 and 0.
     * However, looking at the code:
     * if (q0 < -0.1 || q0 > 0.1) -> Branch 1
     * else if (q0 < 0) -> Branch 2 (This covers -0.1 <= q0 < 0)
     * Formula: 2 * acos(-q0)
     */
    @Test
    public void testGetAngle_Branch2_NegativeQ0_Small() {
        // q0 = -0.05 (Satisfies -0.1 <= q0 < 0)
        double q0 = -0.05;
        double q1 = 0.99874921777; // To ensure it's a valid unit quaternion
        double q2 = 0.0;
        double q3 = 0.0;
        Rotation rotation = new Rotation(q0, q1, q2, q3, true);

        double expected = 2 * FastMath.acos(-q0);
        Assert.assertEquals(expected, rotation.getAngle(), EPSILON);
    }

    /**
     * Tests the third branch (default/final return):
     * q0 is not in (-0.1, 0.1) AND q0 is not < 0
     * This covers 0 <= q0 <= 0.1
     * Formula: 2 * acos(q0)
     */
    @Test
    public void testGetAngle_Branch3_PositiveQ0_Small() {
        // q0 = 0.05 (Satisfies 0 <= q0 <= 0.1)
        double q0 = 0.05;
        double q1 = 0.99874921777;
        double q2 = 0.0;
        double q3 = 0.0;
        Rotation rotation = new Rotation(q0, q1, q2, q3, true);

        double expected = 2 * FastMath.acos(q0);
        Assert.assertEquals(expected, rotation.getAngle(), EPSILON);
    }

    @Test
    public void testGetAngle_Boundary_Zero() {
        // q0 = 0.0
        double q0 = 0.0;
        double q1 = 1.0;
        double q2 = 0.0;
        double q3 = 0.0;
        Rotation rotation = new Rotation(q0, q1, q2, q3, true);

        // Should hit the last return: 2 * acos(0) = 2 * PI/2 = PI
        double expected = Math.PI;
        Assert.assertEquals(expected, rotation.getAngle(), EPSILON);
    }

    @Test
    public void testGetAngle_Boundary_ThresholdNegative() {
        // q0 = -0.1 (Boundary of the first if)
        // Since -0.1 is NOT < -0.1, it goes to 'else if (q0 < 0)'
        double q0 = -0.1;
        double q1 = FastMath.sqrt(1.0 - q0 * q0);
        double q2 = 0.0;
        double q3 = 0.0;
        Rotation rotation = new Rotation(q0, q1, q2, q3, true);

        double expected = 2 * FastMath.acos(-q0);
        Assert.assertEquals(expected, rotation.getAngle(), EPSILON);
    }

    @Test
    public void testGetAngle_Boundary_ThresholdPositive() {
        // q0 = 0.1 (Boundary of the first if)
        // Since 0.1 is NOT > 0.1, it goes to the final return
        double q0 = 0.1;
        double q1 = FastMath.sqrt(1.0 - q0 * q0);
        double q2 = 0.0;
        double q3 = 0.0;
        Rotation rotation = new Rotation(q0, q1, q2, q3, true);

        double expected = 2 * FastMath.acos(q0);
        Assert.assertEquals(expected, rotation.getAngle(), EPSILON);
    }
}
